1	<?php
2	
3	namespace App\Enums;
4	
5	use Filament\Support\Colors\Color;
6	use Filament\Support\Contracts\HasColor;
7	use Filament\Support\Contracts\HasIcon;
8	use Filament\Support\Contracts\HasLabel;
9	
10	/**
11	 * Valori del campo (deprecato ma ancora popolato) `type` dell'API Strava.
12	 * Elenco chiuso e documentato da Strava: nessun nuovo valore atteso.
13	 */
14	enum ActivityType: string implements HasColor, HasIcon, HasLabel
15	{
16	    case AlpineSki = 'AlpineSki';
17	    case BackcountrySki = 'BackcountrySki';
18	    case Canoeing = 'Canoeing';
19	    case Crossfit = 'Crossfit';
20	    case EBikeRide = 'EBikeRide';
21	    case Elliptical = 'Elliptical';
22	    case Golf = 'Golf';
23	    case Handcycle = 'Handcycle';
24	    case Hike = 'Hike';
25	    case IceSkate = 'IceSkate';
26	    case InlineSkate = 'InlineSkate';
27	    case Kayaking = 'Kayaking';
28	    case Kitesurf = 'Kitesurf';
29	    case NordicSki = 'NordicSki';
30	    case Ride = 'Ride';
31	    case RockClimbing = 'RockClimbing';
32	    case RollerSki = 'RollerSki';
33	    case Rowing = 'Rowing';
34	    case Run = 'Run';
35	    case Sail = 'Sail';
36	    case Skateboard = 'Skateboard';
37	    case Snowboard = 'Snowboard';
38	    case Snowshoe = 'Snowshoe';
39	    case Soccer = 'Soccer';
40	    case StairStepper = 'StairStepper';
41	    case StandUpPaddling = 'StandUpPaddling';
42	    case Surfing = 'Surfing';
43	    case Swim = 'Swim';
44	    case Velomobile = 'Velomobile';
45	    case VirtualRide = 'VirtualRide';
46	    case VirtualRun = 'VirtualRun';
47	    case Walk = 'Walk';
48	    case WeightTraining = 'WeightTraining';
49	    case Wheelchair = 'Wheelchair';
50	    case Windsurf = 'Windsurf';
51	    case Workout = 'Workout';
52	    case Yoga = 'Yoga';
53	
54	    public function getLabel(): string
55	    {
56	        return match ($this) {
57	            self::AlpineSki => 'Sci alpino',
58	            self::BackcountrySki => 'Sci fuoripista',
59	            self::Canoeing => 'Canoa',
60	            self::Crossfit => 'Crossfit',
61	            self::EBikeRide => 'E-bike',
62	            self::Elliptical => 'Ellittica',
63	            self::Golf => 'Golf',
64	            self::Handcycle => 'Handbike',
65	            self::Hike => 'Trekking',
66	            self::IceSkate => 'Pattinaggio su ghiaccio',
67	            self::InlineSkate => 'Pattini in linea',
68	            self::Kayaking => 'Kayak',
69	            self::Kitesurf => 'Kitesurf',
70	            self::NordicSki => 'Sci di fondo',
71	            self::Ride => 'Bici',
72	            self::RockClimbing => 'Arrampicata',
73	            self::RollerSki => 'Sci a rotelle',
74	            self::Rowing => 'Canottaggio',
75	            self::Run => 'Corsa',
76	            self::Sail => 'Vela',
77	            self::Skateboard => 'Skateboard',
78	            self::Snowboard => 'Snowboard',
79	            self::Snowshoe => 'Ciaspole',
80	            self::Soccer => 'Calcio',
81	            self::StairStepper => 'Stepper',
82	            self::StandUpPaddling => 'SUP',
83	            self::Surfing => 'Surf',
84	            self::Swim => 'Nuoto',
85	            self::Velomobile => 'Velomobile',
86	            self::VirtualRide => 'Bici virtuale',
87	            self::VirtualRun => 'Corsa virtuale',
88	            self::Walk => 'Camminata',
89	            self::WeightTraining => 'Pesi',
90	            self::Wheelchair => 'Carrozzina',
91	            self::Windsurf => 'Windsurf',
92	            self::Workout => 'Allenamento',
93	            self::Yoga => 'Yoga',
94	        };
95	    }
96	
97	    /**
98	     * Colore per famiglia di sport. I tipi osservati nei dati reali
99	     * dell'app hanno ciascuno una tinta unica; i tipi mai visti finora
100	     * sono raggruppati per famiglia sulle tinte restanti.
101	     *
102	     * @return array{50: string, 100: string, 200: string, 300: string, 400: string, 500: string, 600: string, 700: string, 800: string, 900: string, 950: string}
103	     */
104	    public function getColor(): array
105	    {
106	        return match ($this) {
107	            self::Run => Color::Orange,
108	            self::VirtualRun => Color::Amber,
109	            self::Ride => Color::Blue,
110	            self::Walk => Color::Green,
111	            self::Hike => Color::Emerald,
112	            self::EBikeRide => Color::Cyan,
113	            self::Snowboard => Color::Sky,
114	            self::NordicSki => Color::Indigo,
115	            self::Workout => Color::Violet,
116	            self::Golf => Color::Lime,
117	            self::Yoga => Color::Pink,
118	
119	            self::VirtualRide, self::Velomobile, self::Handcycle => Color::Purple,
120	
121	            self::Canoeing, self::Kayaking, self::Rowing, self::Sail,
122	            self::StandUpPaddling, self::Surfing, self::Swim,
123	            self::Kitesurf, self::Windsurf => Color::Teal,
124	
125	            self::AlpineSki, self::BackcountrySki, self::RollerSki, self::IceSkate => Color::Yellow,
126	
127	            self::Crossfit, self::Elliptical, self::StairStepper, self::WeightTraining => Color::Fuchsia,
128	
129	            self::Soccer, self::Skateboard, self::InlineSkate,
130	            self::RockClimbing, self::Wheelchair => Color::Rose,
131	
132	            self::Snowshoe => Color::Red,
133	        };
134	    }
135	
136	    /**
137	     * Icone Tabler (pacchetto secondnetwork/blade-tabler-icons): Heroicons
138	     * non ha icone sportive dedicate, Tabler sì. Dove manca un'icona
139	     * specifica si usa quella dello sport più simile della stessa famiglia.
140	     */
141	    public function getIcon(): string
142	    {
143	        return match ($this) {
144	            self::Run, self::VirtualRun => 'tabler-run',
145	            self::Ride, self::VirtualRide, self::EBikeRide, self::Velomobile, self::Handcycle => 'tabler-bike',
146	            self::Walk => 'tabler-walk',
147	            self::Hike, self::Snowshoe, self::RockClimbing => 'tabler-mountain',
148	            self::AlpineSki, self::BackcountrySki, self::NordicSki, self::RollerSki => 'tabler-ski-jumping',
149	            self::Snowboard => 'tabler-snowboarding',
150	            self::IceSkate => 'tabler-ice-skating',
151	            self::InlineSkate => 'tabler-roller-skating',
152	            self::Skateboard => 'tabler-skateboarding',
153	            self::Golf => 'tabler-golf',
154	            self::Yoga => 'tabler-yoga',
155	            self::Swim => 'tabler-swimming',
156	            self::Kayaking, self::Canoeing, self::Rowing, self::StandUpPaddling => 'tabler-kayak',
157	            self::Sail, self::Windsurf, self::Kitesurf, self::Surfing => 'tabler-sailboat',
158	            self::Soccer => 'tabler-ball-football',
159	            self::Wheelchair => 'tabler-wheelchair',
160	            self::Crossfit, self::WeightTraining, self::Workout => 'tabler-barbell',
161	            self::Elliptical => 'tabler-treadmill',
162	            self::StairStepper => 'tabler-stairs',
163	        };
164	    }
165	
166	    /**
167	     * Le attività a piedi si esprimono in passo (min/km), le altre in km/h.
168	     */
169	    public function getSpeedUnit(): SpeedUnit
170	    {
171	        return match ($this) {
172	            self::Run, self::VirtualRun, self::Walk, self::Hike, self::Snowshoe => SpeedUnit::MinutesPerKilometer,
173	            default => SpeedUnit::KilometersPerHour,
174	        };
175	    }
176	
177	    public function formatSpeed(?float $metersPerSecond): string
178	    {
179	        return $this->getSpeedUnit()->format($metersPerSecond);
180	    }
181	}
